import java.util.*;public class Student{private final String name,department;private final List<NotificationChannel> channels=new ArrayList<>();public Student(String n,String d){if(n==null||n.trim().isEmpty()||d==null||d.trim().isEmpty())throw new IllegalArgumentException();name=n;department=d;}public String getName(){return name;}public String getDepartment(){return department;}public void addPreferredChannel(NotificationChannel c){if(c==null)throw new IllegalArgumentException();if(!channels.contains(c))channels.add(c);}public List<NotificationChannel> getPreferredChannels(){return Collections.unmodifiableList(channels);}}